fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| rsplit_single(&s, &sep, maxsplit))
        .collect()
}

fn rsplit_single(s: &str, sep: &str, maxsplit: u8) -> Vec<String> {
    if maxsplit == 0 {
        return vec![s.to_string()];
    }
    
    if s.is_empty() {
        return vec![String::new()];
    }
    
    let mut result = Vec::new();
    let mut remaining = s;
    let mut splits_done = 0;
    
    while splits_done < maxsplit {
        if let Some(pos) = remaining.rfind(sep) {
            let right_part = &remaining[pos + sep.len()..];
            result.push(right_part.to_string());
            remaining = &remaining[..pos];
            splits_done += 1;
        } else {
            break;
        }
    }
    
    result.push(remaining.to_string());
    result.reverse();
    
    result
}